sys_script.script:
(function executeRule(current, previous) {

    var LAB_TEST_REQUEST_SYS_ID = 'e0c8c87147d01310273a565a516d434b';

    if (current.getValue('cat_item') != LAB_TEST_REQUEST_SYS_ID) {
        return;
    }

    // Get catalog variables
    var patientId = current.variables.patient.toString();
    var labTestId = current.variables.lab_test.toString();
    var hospitalId = current.variables.hospital.toString();

    if (!labTestId || !patientId || !hospitalId) {
        return;
    }

    // Prevent duplicate Charge Line
    var charge = new GlideRecord('x_2223823_apollo_0_charge_line');
    charge.addQuery('source_table', 'sc_req_item');
    charge.addQuery('source_record', current.getUniqueValue());
    charge.query();

    if (charge.next()) {
        return;
    }

    // Get Lab Test Cost
    var labTest = new GlideRecord('x_2223823_apollo_0_lab_test');

    if (!labTest.get(labTestId)) {
        return;
    }

    var amount = labTest.getValue('cost');

    // Find patient's latest Active Appointment
    var appointment = new GlideRecord('x_2223823_apollo_0_appointment');
    appointment.addQuery('patient', patientId);
    appointment.addQuery('active', true);
    appointment.orderByDesc('start_time');
    appointment.setLimit(1);
    appointment.query();

    if (!appointment.next()) {
        return;
    }

    // Get Invoice from Active Appointment
    var invoiceId = appointment.getValue('invoice');

    if (!invoiceId) {
        return;
    }

    // Create Charge Line
    charge.initialize();
    charge.setValue('patient', patientId);
    charge.setValue('hospital', hospitalId);
    charge.setValue('invoice', invoiceId);
    charge.setValue('amount', amount);
    charge.setValue('charge_type', 'lab');
    charge.setValue('status', 'pending');

    charge.setValue('description', 'Lab Test Charge - ' + labTest.getValue('name'));

    charge.setValue('source_table', 'sc_req_item');
    charge.setValue('source_record', current.getUniqueValue());

    charge.insert();

})(current, previous);
